    mul.wide.u32 %r1, blockIdx_x, nclass;        // %r1 = blockIdx.x * num_classes
    mul.wide.u32 %r1, %r1, 2;                    // * sizeof(half)
    add.u64 sample_pred_base, pred, %r1;        // base address of this sample

