    // -------------------------------------------------
    .reg .f32 log2_sum, log_sum;
    lg2.approx.f32 log2_sum, block_sum;
    mul.f32 log_sum, log2_sum, 0.69314718056;    // ln(2)

    // -------------------------------------------------
    // Load prediction for target class
    // -------------------------------------------------
    .reg .u64 tgt_elem_ptr;
    mul.wide.u32 tgt_elem_ptr, tgt_idx, 2;
    add.u64 tgt_elem_ptr, pred, tgt_elem_ptr;
    ld.global.nc.f16 val_f16, [tgt_elem_ptr];
    cvt.f32.f16 val_f32, val_f16;

